from pathlib import Path
out=Path('apps/web/public/products')
def save(name,body,bg='none'):
    defs='''<defs><linearGradient id="metal" x2=".8" y2="1"><stop stop-color="#d7d8cd"/><stop offset=".5" stop-color="#929d94"/><stop offset="1" stop-color="#d9dad0"/></linearGradient><linearGradient id="dark" x2=".8" y2="1"><stop stop-color="#4a594f"/><stop offset="1" stop-color="#172c23"/></linearGradient><linearGradient id="screen" x2="1" y2="1"><stop stop-color="#213d32"/><stop offset="1" stop-color="#849283"/></linearGradient><linearGradient id="gold" x2="1" y2="1"><stop stop-color="#dbc291"/><stop offset="1" stop-color="#9e8051"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="9"/></filter></defs>'''
    out.joinpath(name+'.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 440" fill="none">{defs}{body}</svg>')
shadow='<ellipse cx="260" cy="365" rx="155" ry="15" fill="#294032" opacity=".14" filter="url(#shadow)"/>'
