keys=''
for r in range(5):
 for c in range(14):
  if r==4 and 3<=c<=8: continue
  x,y=87+c*23,151+r*29
  color='#b4a27c' if c==13 or (r==0 and c==0) else '#ecebdc' if c<11 else '#acb6a6'
  keys+=f'<rect x="{x}" y="{y}" width="20" height="24" rx="3" fill="{color}"/><path d="M{x+6} {y+8}h5" stroke="#758074" stroke-width="1"/>'
keys+='<rect x="156" y="267" width="135" height="24" rx="3" fill="#e7e5d5"/>'
