studio='''<rect width="500" height="440" fill="#e4e1d2"/><path d="M325 0h175v440H185z" fill="#d5d5c1"/><path d="M433 0h67v440H297z" fill="#efecdd" opacity=".5"/><path d="M0 302l500-43v181H0z" fill="#b6a786"/><path d="M0 314l500-43v14L0 329z" fill="#d1bea0"/><ellipse cx="260" cy="347" rx="185" ry="23" fill="#4b5742" opacity=".12" filter="url(#shadow)"/><g transform="translate(72 85) scale(.68)">'''+monitor+'''</g><g transform="translate(116 223) scale(.52)">'''+keyboard+'''</g><g transform="translate(279 107) scale(.51)">'''+lamp+'''</g><ellipse cx="69" cy="350" rx="27" ry="10" fill="#606e54" opacity=".17"/><path d="M45 296h44l-5 49H51z" fill="#e8e1c9"/><ellipse cx="67" cy="296" rx="22" ry="7" fill="#b0a68a"/><ellipse cx="67" cy="298" rx="17" ry="4" fill="#716446"/><path d="M89 305c23-5 22 27-4 25" stroke="#e8e1c9" stroke-width="7"/><path d="M430 285l28-3-2 35-26 3z" fill="#c4b18a"/><path d="M443 285v-46m0 22c-30-7-31-20-16-16 13 1 16 15 16 15m0-2c26-13 24-26 13-21-13 5-13 19-13 21" stroke="#5b7453" stroke-width="3"/>'''
